// Trained linear relationship classifier (v2).
//
// Generated by `scripts/train-relationship-linear.py`; do not hand-edit the JSON artifact.
// Boundary-marked Unicode character 1-4 grams feed a pruned multinomial logistic
// regression. It replaces both the fixed Laya relationship question and the v1 Naive
// Bayes model for local analysis after passing the held-out corpus gate.
import modelData from "./relationship-linear-model.json";

interface RelationshipLinearModel {
  version: string;
  algorithm: string;
  features: string;
  corpusSha256: string;
  labels: string[];
  sizes: number[];
  prefix: string;
  suffix: string;
  temperature: number;
  l2: number;
  epochs: number;
  pruneThreshold: number;
  bias: number[];
  weights: Record<string, number[]>;
  vocabSize: number;
  exportedGrams: number;
}

const model = modelData as RelationshipLinearModel;

export const RELATIONSHIP_LINEAR_VERSION = model.version;

export const RELATIONSHIP_LINEAR_LABELS = model.labels;

/** Unique boundary-marked character n-grams. Must mirror the Python trainer. */
export function relationshipTextGrams(text: string): string[] {
  const compact = [model.prefix, ...Array.from(text).filter((char) => !/\s/u.test(char)),
    model.suffix];
  const grams = new Set<string>();
  for (const size of model.sizes) {
    for (let index = 0; index + size <= compact.length; index++) {
      grams.add(compact.slice(index, index + size).join(""));
    }
  }
  return [...grams];
}

/** Normalized class probabilities for one relationship text. Deterministic. */
export function relationshipTextProbabilities(text: string): Record<string, number> {
  const scores = [...model.bias];
  for (const gram of relationshipTextGrams(text)) {
    const values = model.weights[gram];
    if (!values) continue;
    for (let index = 0; index < scores.length; index++) {
      scores[index] = scores[index]! + (values[index] ?? 0);
    }
  }
  const calibrated = scores.map((score) => score / model.temperature);
  const maximum = Math.max(...calibrated);
  const exponents = calibrated.map((score) => Math.exp(score - maximum));
  const total = exponents.reduce((sum, value) => sum + value, 0);
  return Object.fromEntries(model.labels.map((label, index) =>
    [label, total > 0 ? exponents[index]! / total : 1 / model.labels.length]));
}
